mapper.select:
SELECT u.* FROM user u WHERE u.isDelete = 0 AND u.userStatus = 0
AND ( u.username LIKE CONCAT('%', #{keyword}, '%') OR u.userAccount LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM user_tag keyword_ut JOIN tag keyword_t ON keyword_t.id = keyword_ut.tagId WHERE keyword_ut.userId = u.id AND keyword_t.isDelete = 0 AND keyword_t.tagName LIKE CONCAT('%', #{keyword}, '%') ) )
AND ( SELECT COUNT(DISTINCT selected_t.tagName) FROM user_tag selected_ut JOIN tag selected_t ON selected_t.id = selected_ut.tagId WHERE selected_ut.userId = u.id AND selected_t.isDelete = 0 AND selected_t.tagName IN
#{tagName}
) = #{tagCount}
ORDER BY u.createTime DESC, u.id DESC

SELECT u.*
FROM user u
WHERE u.isDelete = 0
  AND (
    u.id = #{userId}
    OR EXISTS (
      SELECT 1
      FROM cardRoomMember current_member
      JOIN cardRoomMember shared_member
        ON shared_member.roomId = current_member.roomId
      WHERE current_member.userId = #{userId}
        AND shared_member.userId = u.id
    )
  )
ORDER BY u.totalScore DESC, u.wins DESC, u.id ASC
LIMIT #{limit}
